const GB = 1024 ** 3;
function tailRam({ activeTraces, spansPerTrace, bytesPerSpan }) {
  return (activeTraces * spansPerTrace * bytesPerSpan) / GB;
}
// Reference A: 50k in-flight traces, 100 spans each, 1 KB/span.
const a = tailRam({ activeTraces: 50000, spansPerTrace: 100, bytesPerSpan: 1024 });
console.log('A:', a.toFixed(1), 'GB');
// Reference B: 10k req/s held for a 30s window => 300k active traces, 10 spans, 1 KB.
const b = tailRam({ activeTraces: 10000 * 30, spansPerTrace: 10, bytesPerSpan: 1024 });
console.log('B:', b.toFixed(1), 'GB');
// Try it: double the decision window from 30s to 60s and RAM doubles.
const b60 = tailRam({ activeTraces: 10000 * 60, spansPerTrace: 10, bytesPerSpan: 1024 });
console.log('B@60s:', b60.toFixed(1), 'GB');
